    private static Button Button(Control owner,string label,Action action)
    {var button=new Button {Text=label};button.Pressed+=()=>{if(Fresh(owner,button))action();};return button;}
    public void ready(Control owner)
    {
        owner.Name=owner.Get("templates_only").AsBool()?"ShaderTemplates":"ShaderSamples";var theme=new Theme {DefaultFontSize=13};theme.SetColor("font_color","Label",new Color("d7e4ec"));theme.SetStylebox("normal","Button",box(new Color("182936"),new Color("304958")));theme.SetStylebox("hover","Button",box(new Color("223d46"),new Color("67cbb4")));theme.SetStylebox("pressed","Button",box(new Color("254b48"),new Color("7be0c6")));owner.Theme=theme;owner.SizeFlagsVertical=Control.SizeFlags.ExpandFill;((SplitContainer)owner).SplitOffsets=new[]{195};owner.Set("entries",new ShaderSampleCatalogOperations().get_entries());load_preferences(owner);build_sidebar(owner);build_content(owner);
        var live=new ShaderSamplePreview {Name="LibraryLivePreview"};owner.Set("live",live);owner.AddChild(live);live.Size=new Vector2I(640,384);var thumbnail=new ShaderSamplePreview {Name="LibraryThumbnailWorker"};owner.Set("thumbnail",thumbnail);owner.AddChild(thumbnail);thumbnail.Size=new Vector2I(256,160);Node<TextureRect>(owner,"preview_display").Texture=live.GetTexture();owner.VisibilityChanged+=()=>visibility_changed(owner);refresh(owner);
    }
    public void draw(Control owner)=>owner.DrawRect(new Rect2(Vector2.Zero,owner.Size),new Color("101923"));
    public void build_sidebar(Control owner)
