        var side=new VBoxContainer {CustomMinimumSize=new Vector2(155,0)};side.AddThemeConstantOverride("separation",9);owner.AddChild(side);var search=Node<LineEdit>(owner,"search");search.PlaceholderText="Search shaders...";search.ClearButtonEnabled=true;search.TextChanged+=text=>refresh(owner);side.AddChild(search);var type=Node<OptionButton>(owner,"type_filter");foreach(string label in new[]{"All shader types","2D","3D","Sky","Fog","Particles"})type.AddItem(label);type.ItemSelected+=index=>refresh(owner);side.AddChild(type);var category=Node<OptionButton>(owner,"category_filter");Categories(owner);category.ItemSelected+=index=>refresh(owner);side.AddChild(category);var collection=Node<OptionButton>(owner,"collection_filter");foreach(string label in new[]{"All","Favorites","Recently used"})collection.AddItem(label);collection.ItemSelected+=index=>refresh(owner);side.AddChild(collection);var count=Node<Label>(owner,"count");count.AutowrapMode=TextServer.AutowrapMode.WordSmart;side.AddChild(count);var help=new Label {Text="Actual shader renders\n\nDrag the large preview to orbit. Use the wheel to zoom. Uniform changes are temporary.",AutowrapMode=TextServer.AutowrapMode.WordSmart};help.AddThemeColorOverride("font_color",new Color("91a6b5"));side.AddChild(help);
