    public void build_content(Control owner)
    {
        var split=new HSplitContainer {SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,SplitOffsets=new[]{440}};owner.AddChild(split);var scroll=Node<ScrollContainer>(owner,"card_scroll");scroll.CustomMinimumSize=new Vector2(180,0);scroll.HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled;scroll.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;split.AddChild(scroll);var grid=Node<GridContainer>(owner,"grid");grid.Columns=2;grid.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;grid.AddThemeConstantOverride("h_separation",8);grid.AddThemeConstantOverride("v_separation",8);scroll.AddChild(grid);var detailScroll=new ScrollContainer {CustomMinimumSize=new Vector2(300,0),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled};split.AddChild(detailScroll);var detail=new VBoxContainer {SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,SizeFlagsVertical=Control.SizeFlags.ExpandFill};detailScroll.AddChild(detail);
        var heading=Node<Label>(owner,"heading");heading.AddThemeFontSizeOverride("font_size",20);heading.AutowrapMode=TextServer.AutowrapMode.WordSmart;detail.AddChild(heading);var display=Node<TextureRect>(owner,"preview_display");display.CustomMinimumSize=new Vector2(0,185);display.ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize;display.StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered;display.GuiInput+=input=>preview_input(owner,input);detail.AddChild(display);var error=Node<Label>(owner,"preview_error");error.AutowrapMode=TextServer.AutowrapMode.WordSmart;error.AddThemeColorOverride("font_color",new Color("ff9b8e"));error.Hide();detail.AddChild(error);var tools=new HBoxContainer();detail.AddChild(tools);var geometry=Node<OptionButton>(owner,"geometry");foreach(string label in new[]{"Sphere","Plane","Cube"})geometry.AddItem(label);geometry.ItemSelected+=index=>Live(owner).set_geometry(new[]{"sphere","plane","cube"}[index]);tools.AddChild(geometry);tools.AddChild(Button(owner,"Reset preview",()=>select(owner,Data(owner,"selected"))));var favorite=Button(owner,"Favorite",()=>toggle_favorite(owner));favorite.ToggleMode=true;owner.Set("favorite",favorite);tools.AddChild(favorite);
        var description=Node<Label>(owner,"description");description.AutowrapMode=TextServer.AutowrapMode.WordSmart;description.AddThemeFontSizeOverride("font_size",12);detail.AddChild(description);var uniformScroll=new ScrollContainer {CustomMinimumSize=new Vector2(0,95),HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled};detail.AddChild(uniformScroll);var uniforms=Node<VBoxContainer>(owner,"uniforms");uniforms.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;uniformScroll.AddChild(uniforms);var source=Node<CodeEdit>(owner,"source");source.Editable=false;source.GuttersDrawLineNumbers=true;source.SizeFlagsVertical=Control.SizeFlags.ExpandFill;source.CustomMinimumSize=new Vector2(0,110);source.AddThemeFontSizeOverride("font_size",12);var highlighter=new CodeHighlighter {NumberColor=new Color("b5cea8"),FunctionColor=new Color("dcdcaa")};foreach(string keyword in new[]{"shader_type","render_mode","uniform","varying","group_uniforms","if","else","for","return","discard"})highlighter.AddKeywordColor(keyword,new Color("c792ea"));foreach(string type in new[]{"float","int","bool","vec2","vec3","vec4","mat3","mat4","void","sampler2D"})highlighter.AddKeywordColor(type,new Color("62d6ca"));highlighter.AddColorRegion("//","",new Color("6a9955"),true);highlighter.AddColorRegion("/*","*/",new Color("6a9955"));source.SyntaxHighlighter=highlighter;detail.AddChild(source);
        var actions=new HFlowContainer();detail.AddChild(actions);actions.AddChild(Button(owner,"Copy Code",()=>copy(owner)));actions.AddChild(Button(owner,"Open in Editor",()=>open(owner)));actions.AddChild(Button(owner,"Create Shader File",()=>save_file(owner)));var apply=Button(owner,"Apply to Selected Actor",()=>this.apply(owner));owner.Set("apply",apply);actions.AddChild(apply);var status=Node<Label>(owner,"status");status.AutowrapMode=TextServer.AutowrapMode.WordSmart;status.AddThemeFontSizeOverride("font_size",12);detail.AddChild(status);
